 public override void _Ready(){try{
 var path=OS.GetEnvironment("C07_SOUTH_BEARING_SCENE");if(path.Length==0)path="res://central-south-reconstructed.json";
 var e=new BattleEngine(PresentationJson.Load<JsonArray>("res://data/content-packs.json"));var l=PresentationJson.Load<JsonArray>("res://data/grayflag-campaign-levels.json").OfType<JsonObject>().Single(v=>v["id"]!.GetValue<string>()=="c01-07");var s=e.CreateState(l);var digest=EcmaJson.Stringify(s);var sc=AuthoredScene.Load(path);var r=BoardSceneRendering.Load(sc,l,s["map"]!.AsObject());var b=new BoardView{AnimationsEnabled=false};AddChild(b);b.Configure(new(AssetCatalog.Load(),EnvironmentCatalog.Load(),e.Grids.Get("square4"),e.Catalog,r.Plane),l,sc);BoardGroundView? ground=null;b.ConfigureGround((rules,scene)=>ground=r.Ground(rules,scene));b.ConfigureDynamicState();var shown=s.DeepClone().AsObject();shown["units"]=new JsonArray();b.RenderState(shown);
 var scene=PresentationJson.Load<JsonObject>(path);var layout=PresentationJson.Load<JsonObject>(scene["assembledGroundPath"]!.GetValue<string>());var inst=layout["objects"]!.AsArray().OfType<JsonObject>().Single(v=>v["id"]!.GetValue<string>()=="central-south-left-planter");var catalog=PresentationJson.Load<JsonObject>(layout["objectCatalogPath"]!.GetValue<string>());var asset=catalog["objects"]![inst["assetId"]!.GetValue<string>()]!;var doc=PresentationJson.Load<SceneSurfaceDocument>(asset["surfaceGeometryPath"]!.GetValue<string>());
 var entries=ground!.DepthEntries.Where(v=>v.Visual is not null&&v.Node.Name.ToString().StartsWith("central-south-left-planter__surface_")).ToArray();string Owner(Node2D n){int i=int.Parse(n.Name.ToString().Split("__surface_")[1]);return doc.Supports[i].Id;}
 var roots=entries.Where(v=>Owner(v.Node)=="physical-soil-root").ToArray();if(roots.Length!=1)throw new Exception("One actual root support required");var rows=new JsonArray();
