 var report=new JsonObject{{"scope","Formal runtime material and pair-order audit of soil/back rims/root. Draw/pick compiler source, no second wrapper; static empty display clone, no commands/saves."},{"scene",path},{"pairs",rows},{"stoneMaterialOwners",material},{"stateUnchanged",digest==EcmaJson.Stringify(s)},{"issues",b.RenderingIssueCount}};var output=OS.GetEnvironment("C07_SOUTH_ASSEMBLY_OUTPUT");if(output.Length==0)output="res://central-south-assembly-ownership-result.json";File.WriteAllText(ProjectSettings.GlobalizePath(output),report.ToJsonString());
 if(rows[0]!["actualMaterialOverlap"]!.GetValue<int>()==0||rows[0]!["wrongOverPlant"]!.GetValue<int>()!=0)throw new Exception("Carrying soil plane must not swallow actual rooted foliage");if(rows.Skip(1).Any(v=>v!["wrongOverPlant"]!.GetValue<int>()!=0))throw new Exception("Rear wooden rim must not borrow front foot over actual rooted foliage");if(digest!=EcmaJson.Stringify(s)||b.RenderingIssueCount!=0)throw new Exception("Static assembly state/render changed");GD.Print("CENTRAL_SOUTH_ASSEMBLY_OWNERSHIP_COMPLETE");GetTree().Quit();
 }catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
